import java.util.ArrayList;
import java.util.List;

public class Main {
    record Contact(String name, String phone) { }
    public static void main(String[] args) {
        List<Contact> contacts = new ArrayList<>(List.of(
            new Contact("Ada", "555-0101"), new Contact("Grace", "555-0102")));
        String query = "Grace";
        contacts.stream().filter(c -> c.name().equalsIgnoreCase(query)).findFirst()
            .ifPresentOrElse(c -> System.out.println(c.name() + ": " + c.phone()),
                             () -> System.out.println("Contact not found"));
    }
}
